from typing import List, Any

def unique(l: list) -> List[Any]:
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    if not isinstance(l, list):
        raise TypeError("Input must be a list")
    if not l:
        return []
    # Creating a set will remove duplicates; will raise TypeError if elements are unhashable.
    try:
        unique_set = set(l)
    except TypeError as e:
        # Provide a clearer error message while preserving original exception context.
        raise TypeError("List contains unhashable elements; cannot determine uniqueness using a set") from e
    return sorted(unique_set)
